module top_module(
  input clk,
  input reset,
  output reg [2:0] count,
  output reg done
);reg [1:0] state;

  always @(posedge clk, negedge reset) begin
    if (!reset) begin
      state <= 2'b00;
      count <= 3'b000;
      done <= 1'b1;
    end
    else begin
      done <= 1'b0;
      case (state)
        2'b00: begin
          count <= 3'b000;
          state <= 2'b01;
        end
        2'b01: begin
          count <= count + 1;
          if (count == 3'b010) begin
            state <= 2'b10;
          end
        end
        2'b10: begin
          count <= count + 1;
          if (count == 3'b100) begin
            state <= 2'b11;
          end
        end
        2'b11: begin
          count <= count + 1;
          if (count == 3'b111) begin
            state <= 2'b00;
            done <= 1'b1;
          end
        end
      endcase
    end
  end

endmodule

