description:
Design a one-hot state machine with n states, implemented as a register that cycles through the states on each clock pulse. The state machine enters a default state when reset, which corresponds to the first state (indicated by a one-hot encoding). On each clock cycle, the state transitions to the next state in a predefined sequence (from 0001 to 0010, then to 0100, then to 1000, and back to 0001). The output signals represent the current state, with only one output being high at any time, following the definition of one-hot encoding.
module top_module(
  input clk,
  input rst,
  output reg [n-1:0] out
);

code:
module top_module(
  input clk,
  input rst,
  output reg [n-1:0] out
);parameter n = 4; // number of output signals

reg [n-1:0] state;
always @ (posedge clk) begin
  if (rst) begin
    state <= {n{1'b0}} | 1'b1; // reset to default state
  end else begin
    case (state)
      // define states as unique binary codes
      4'b0001: state <= 4'b0010;
      4'b0010: state <= 4'b0100;
      4'b0100: state <= 4'b1000;
      4'b1000: state <= 4'b0001;
      default: state <= {n{1'b0}} | 1'b1; // reset to default state if invalid state
    endcase
  end
end

// connect outputs to flip-flops based on current state
always @ (state) begin
  out = {n{1'b0}};
  out[state] = 1'b1;
end

endmodule

