module mealy_machine (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter A=0, B=1, C=2;

    always_comb begin
        case (state)
            A: begin
                next_state = in ? B : C;
                out = in ? 1 : 0;
            end
            B: begin
                next_state = in ? C : A;
                out = in ? 0 : 1;
            end
            C: begin
                next_state = in ? A : B;
                out = in ? 1 : 0;
            end
        endcase
    end

endmodule

