description:
Design a synchronous 4-bit binary counter. The counter increments its value on the rising edge of the clock signal (clk). When the reset signal (rst) is asserted, the counter is initialized to zero. The current count value is output as a 4-bit wide signal.
module top_module(
input  wire clk,
input  wire rst,
output wire [3:0] count
);

code:
module top_module(
input  wire clk,
input  wire rst,
output wire [3:0] count
);reg [3:0] counter_reg;

always @(posedge clk or posedge rst)
    if (rst)
        counter_reg <= 4'b0000;
    else
        counter_reg <= counter_reg + 1;

assign count = counter_reg;

endmodule

