		assign o_op1 = i_adr1==0 ? 0 : mem[i_adr1];
		assign o_op2 = i_adr2==0 ? 0 : mem[i_adr2];
		assign o_op3 = i_adr3==0 ? 0 : mem[i_adr3];
	 always @(posedge clk or posedge rst) begin
