module top_module(
    input D,
    input EN,
    input CLK,
    output Q,
    output Q_N
);reg q;

always @(posedge CLK) begin
    if (!EN) begin
        q <= q;
    end else begin
        q <= D;
    end
end

assign Q = q;
assign Q_N = ~q;

endmodule

