reg [3:0] stage2;

always @ (posedge clk) begin
    stage1 <= ~binary;
end

always @ (posedge clk) begin
    stage2 <= stage1;
end

always @ (posedge clk) begin
    ones_comp <= stage2;  // Updated to register assignment inside clk context
end

endmodule

