module top_module(
  input [n-1:0] in,
  input clk,
  input wen,
  input rst,
  output [m-1:0] out
);parameter n = 8; // number of input signals
parameter m = 4; // number of output signals
parameter r = 16; // number of registers

reg [r-1:0] registers;

// D flip-flops with enable signals
always @(posedge clk or posedge rst) begin
  if (rst) begin
    registers <= 0;
  end else if (wen) begin
    registers <= {registers[r-1-m:0], in};
  end
end

// Output the current values
assign out = registers[r-1:r-m];

endmodule

