  always @(negedge clk) begin 
  if (wea) 
  RAM[addra] <= dia; 
  doa <= RAM[addra]; 
  end 
  always @(negedge clk) begin 
  if (web) 
  RAM[addrb] <= dib; 
  dob <= RAM[addrb]; 
  end 
 endmodule

